import { Box } from "@mui/system";
import axios from "axios";
import React, { useEffect, useState } from "react";
import toast from "react-hot-toast";
import { Portal } from "react-portal";
import { useLocation, useNavigate } from "react-router-dom";
import { BounceLoader } from "react-spinners";
import CustomAppBar from "../../core/components/appbar/AppBar";
import { baseUrl } from "../../core/config/config";
import { posTag } from "../../shared/sharingVar";

export default function Sentence() {
  const { state } = useLocation();
  const [isLoading, setisLoading] = useState(false);
  let navigate = useNavigate();
  // const { input: output } = state;

  useEffect(() => {
    if (localStorage.getItem("isAdmin") === "true") {
      navigate("/admin");
      return;
    }
  }, [navigate]);

  const output =
    state == null
      ? []
      : state.map((e) => {
          return e.input;
        });

  const onDone = async () => {
    try {
      setisLoading(true);
      const response = await axios.post(`${baseUrl}doc/markedReady`, {
        ids: state.map((e) => {
          return e._id;
        }),
      });
      console.log(response);

      if (response.data.message) {
        toast.error(response.data.message);
        setisLoading(false);
        return;
      }
      setisLoading(false);

      await toast.promise(
        axios.get(`${baseUrl}doc/assign/self`, {
          headers: {
            "Content-Type": "application/json",
            Accept: "application/json",
            Authorization: `Bearer ${localStorage.getItem("token")}`,
          },
        }),
        {
          loading: "Assigning...",
          success: <b>Assinged!</b>,
          error: <b>Could not assign.</b>,
        }
      );

      navigate("/");
      posTag.clear();
    } catch (err) {
      toast.error("Error processing");
      console.log(err);
      setisLoading(false);
    }
  };

  const onSubmit = async (input, index) => {
    try {
      setisLoading(true);
      let headers = new Headers();

      headers.append("Content-Type", "application/json");
      headers.append("Accept", "application/json");
      headers.append("Access-Control-Request-Headers", "*");
      const response = await axios.post(`${baseUrl}doc/word-tokenisation`, {
        header: headers,
        input: input,
      });
      console.log(response);

      if (response.data.message) {
        toast.error(response.data.message);
        setisLoading(false);
        return;
      }
      setisLoading(false);

      navigate("/word/", {
        state: {
          data: response.data[0].output,
          sentences: state,
          index: index,
        },
      });
    } catch (err) {
      setisLoading(false);
      toast.error("Error processing");
      console.log(err);
    }
  };

  return (
    <div className="word-root">
      <CustomAppBar label="User Panel" shouldBack={false} />
      <Box sx={{ height: 8 }} />
      <div className="bs">
        <div className="elements">
          {output.map((e, i) => {
            return (
              <div key={i} className="card">
                <div className="left">
                  <p>{e}</p>
                </div>
                <div className="right">
                  <button
                    className={`btn-select ${posTag.has(i) ? "filled" : ""}`}
                    type="submit"
                    name="button"
                    onClick={() => onSubmit(e, i)}
                  >
                    {posTag.has(i) && "Selected"}
                    {!posTag.has(i) && "Select"}
                  </button>
                </div>
              </div>
            );
          })}
        </div>
        <div className="submitBtn">
          <button className={`dropbtn`} onClick={onDone}>
            Done
          </button>
        </div>
        {isLoading && (
          <Portal node={document && document.getElementById("loader")}>
            <div className="loader-context">
              <BounceLoader color={"#ffffff"} loading={true} size={60} />
            </div>
          </Portal>
        )}
      </div>
    </div>
  );
}
